metrics.workdir_dsl:
workspace "Bookshop" "A simple online bookshop" {
    configuration {
        scope softwaresystem
    }

    model {
        customer = person "Customer" "A customer who browses and purchases books"
        bookshop = softwareSystem "Bookshop" "An online bookshop where customers can browse and purchase books"
        database = softwareSystem "Bookshop Database" "The database that stores book and order data" {
            tags "Database"
        }
        paymentProvider = softwareSystem "Payment Provider" "An external payment provider that processes credit card payments" {
            tags "External"
        }

        customer -> bookshop "Browses and purchases books through" "HTTPS"
        bookshop -> database "Stores and retrieves book and order data" "SQL"
        bookshop -> paymentProvider "Sends payment details to" "REST API"
    }

    views {
        systemContext bookshop "SystemContext" "A system context diagram showing the Bookshop and its users and external systems" {
            include *
            autoLayout
        }
    }
}
